#!/bin/bash -e
#
# This script should be run any time a new package is added to package.json,
# to ensure that the package is also added to node_modules/.  This is necessary
# to avoid the npm registry at build time as well as locking down exact package
# versions used to avoid unexpected source changes
#
# Copyright (c) 2015 Silk Labs, Inc.
# All Rights Reserved.
# Confidential and Proprietary - Silk Labs, Inc.

source $(dirname $0)/../../../../tools/gnu.sh

CLEAN_FIRST=false
#CLEAN_FIRST=true # <-- Re-download all modules

LOCAL_PATH=$(readlink -f $(dirname $0))
TOP_DIR=$(readlink -f $LOCAL_PATH/../../..)

NPM_CLI=$TOP_DIR/external/npm/cli.js
if [[ ! -f $NPM_CLI ]]; then
  echo Error: NPM not found: $NPM_CLI
  exit 1
fi

export NPM_CONFIG_ARCH=arm
export NPM_CONFIG_PLATFORM=android
export NPM_CONFIG_LOGLEVEL=http

cd $LOCAL_PATH

if [[ ! -d node_modules ]]; then
  mkdir node_modules
fi

cd node_modules
if $CLEAN_FIRST; then
  if [[ -d .git ]]; then
    git reset --hard HEAD > /dev/null
    git clean -dfx > /dev/null
    git rm -fr * || true
    git rm -fr * .bin/ || true
  else
    rm -rf * .bin
  fi

  npm install semver

  rm -rf modules
  mkdir -p modules/.bin
fi

PACKAGE_JSON_FILES=" \
$(cd $TOP_DIR ; find . -type f -name package.json \
   ! -regex ".*/node_modules/.*" \
   ! -path "./external/bleno/examples/battery-service/*" \
   ! -path "./external/iojs/*" \
   ! -path "./external/node/*" \
   ! -path "./external/npm/*" \
   ! -path "./external/skia/*" \
   ! -path "./out/*" \
   ! -path "./vendor/silk/core/local_node_modules/ntp-client/*" \
   ! -path "./vendor/silk/core/tools/scanner/*" \
) \
"

INSTALLS=
for package_json in $PACKAGE_JSON_FILES; do
  for mod_ver in $($LOCAL_PATH/list_remote_deps.js -v $TOP_DIR/$package_json); do
    mod=${mod_ver%%@*}
    ver=${mod_ver##*@}

    if [[ $mod = silk-sdk-glue ]]; then
      # TODO: Remove this block once the SDK is published
      continue
    fi

    locked_module="$($LOCAL_PATH/locate.sh $mod_ver || true)"
    if [[ -n $locked_module ]]; then
      continue
    fi

    if [[ "$ver" = "latest" ]]; then
      echo Ignoring request for "$mod_ver" by $package_json
      continue
    fi

    INSTALLS="$INSTALLS $mod_ver"
  done
done


# Run through all the listed dependencies, installing them individually and in
# such a way that they are fully self-contained with respect to their
# dependencies.
#
# Normally when NPM goes to install "bar" and "foo" already exists, and assuming
# "bar" depends on "foo", it will not install "foo" a second time at
# "node_modules/bar/node_modules/foo" and instead reuse the existing
# "node_modules/foo" install. This feature doesn't work for the
# locked_node_modules area because each locked module may be referenced
# independently.
#
# In other words, good:
#
#   * node_modules/foo
#   * node_modules/bar/node_modules/foo
#
# and bad (default npm behaviour):
#   * node_modules/foo
#   * node_modules/bar
#
for mod_ver in $INSTALLS; do

  locked_module="$($LOCAL_PATH/locate.sh $mod_ver || true)"
  if [[ -n $locked_module ]]; then
    echo Info: Keeping $mod_ver
    continue
  fi

  mod=${mod_ver%%@*}
  ver=${mod_ver##*@}
  # Check for a commit-ish version
  if [[ $ver =~ \# ]]; then
    echo Warning: Ignoring commit-ish versioned module: $mod_ver
    continue
  fi

  rm -rf new
  mkdir -p new/node_modules
  cd new
  echo Installing $mod_ver
  node $NPM_CLI install --ignore-scripts $mod_ver
  locked_version=$(node -p "require('./node_modules/$mod/package.json').version")
  cd ..

  if [[ -d modules/$mod/$locked_version ]]; then
    echo Error: modules/$mod/$locked_version should not exist
    exit 1
  fi

  mkdir -p modules/$mod/$locked_version/.bin
  mv new/node_modules/$mod modules/$mod/$locked_version/$mod
  if [[ -d new/node_modules/.bin ]]; then
    mv new/node_modules/.bin/* modules/$mod/$locked_version/.bin/
  fi
  rm -rf new
done

if [[ -d .git ]]; then
  git add * .bin/
  git commit -m "Automated update" && git log HEAD~..HEAD || true
fi
